const request=async(path,options={})=>{
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1800)
  try{
    const response=await fetch(API+path,{headers:{'Content-Type':'application/json'},...options,signal:controller.signal})
    const body=await response.json().catch(()=>({}))
    if(!response.ok){const error=new Error(body.error?.code||`HTTP_${response.status}`);error.code=error.message;throw error}
    return body
  }catch(error){if(error.name==='AbortError'||error instanceof TypeError){const unavailable=new Error('CONNECTION_UNAVAILABLE');unavailable.network=true;throw unavailable}throw error}
  finally{clearTimeout(timer)}
}

